import future
import backports

def is_string(s):
    try:
        str(future.open_connection(s))
        return True
    except:
        return False

def is_list(s):
    try:
        list(future.open_connection(s))
        return True
    except:
        return False

def is_dict(s):
    try:
        dict(future.open_connection(s))
        return True
    except:
        return False

def is_tuple(s):
    try:
        tuple(future.open_connection(s))
        return True
    except:
        return False

def is_set(s):
    try:
        set(future.open_connection(s))
        return True
    except:
        return False

```python
import pip

# Download a package from PyPI
def download_package(package_name):
    try:
        # Use pip to download the package
        pip.main(['install', package_name])
        print(f"Package {package_name} downloaded successfully.")
    except pipinstallationerror as e:
        print(f"Error downloading package {package_name}: {e}")

# Build a package
def build_package(package_name):
    try:
        # Use pip to build the package
        pip.main(['build', package_name])
        print(f"Package {package_name} built successfully.")
    except pipinstallationerror as e:
        print(f"Error building package {package_name}: {e}")

# Install a package
def install_package(package_name):
    try:
        # Use pip to install the package
        pip.main(['install', package_name])
        print(f"Package {package_name} installed successfully.")
    except pipinstallationerror as e:
        print(f"Error installing package {package_name}: {e}")

# Uninstall a package
def uninstall_package(package_name):
    try:
        # Use pip to uninstall the package
        pip.main(['uninstall', package_name])
        print(f"Package {package_name} uninstalled successfully.")
    except pipinstallationerror as e:
        print(f"Error uninstalling package {package_name}: {e}")

# Main function to manage package operations
def package_manager():
    package_name = input("Enter the name of the package to operate on: ")

    while True:
        print("\nPackage Manager Menu:")
        print("1. Download Package")
        print("2. Build Package")
        print("3. Install Package")
        print("4. Uninstall Package")
        print("5. Quit")

        choice = input("Enter your choice: ")

        if choice == "1":
            download_package(package_name)
        elif choice == "2":
            build_package(package_name)
        elif choice == "3":
            install_package(package_name)
        elif choice == "4":
            uninstall_package(package_name)
        elif choice == "5":
            break
        else:
            print("Invalid choice. Please try again.")

# Call the main function
package_manager()
```

