import struct

class ASN1Type:
    def __init__(self, name, type):
        self.name = name
        self.type = type

    def to_bytes(self, length):
        if self.type == 'bitString':
            return b'\x00' * length
        elif self.type == 'int32':
            return struct.pack('<I', length)
        elif self.type == 'uint32':
            return struct.pack('<Q', length)
        elif self.type == 'int64':
            return struct.pack('<I', length)
        elif self.type == 'uint64':
            return struct.pack('<Q', length)
        elif self.type == 'octetString':
            return b'\x01' * length
        elif self.type == 'generalizedTime':
            return struct.pack('<Q', length)
        elif self.type == 'setOfGeneralizedTime':
            return struct.pack('<Q', length)
        elif self.type == 'bitString':
            return b'\x00' * length
        elif self.type == 'boolean':
            return struct.pack('<B', 0 if self.value else 1)
        elif self.type == 'octetString':
            return b'\x01' * length
        elif self.type == 'generalizedTime':
            return struct.pack('<Q', length)
        elif self.type == 'setOfGeneralizedTime':
            return struct.pack('<Q', length)
        else:
            raise ValueError(f"Unsupported ASN.1 type: {self.type}")

class DERCodec:
    def encode(self, asn1_type):
        if asn1_type.type == 'bitString':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'int32':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'uint32':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'int64':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'uint64':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'octetString':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'generalizedTime':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'setOfGeneralizedTime':
            return asn1_type.to_bytes(asn1_type.length)
        elif asn1_type.type == 'boolean':
            return asn1_type.to_bytes(asn1_type.length)
        else:
            raise ValueError(f"Unsupported ASN.1 type: {asn1_type.type}")

class BERCodec:
    def encode(self, asn1_type):
        if asn1_type.type == 'bitString':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'int32':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'uint32':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'int64':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'uint64':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'octetString':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'generalizedTime':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'setOfGeneralizedTime':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'boolean':
            return selfDERCodec().encode(asn1_type)
        else:
            raise ValueError(f"Unsupported ASN.1 type: {asn1_type.type}")

class X208Codec:
    def encode(self, asn1_type):
        if asn1_type.type == 'bitString':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'int32':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'uint32':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'int64':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'uint64':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'octetString':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'generalizedTime':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'setOfGeneralizedTime':
            return selfDERCodec().encode(asn1_type)
        elif asn1_type.type == 'boolean':
            return selfDERCodec().encode(asn1_type)
        else:
            raise ValueError(f"Unsupported ASN.1 type: {asn1_type.type}")

def main():
    asn1_type = ASN1Type('exampleType', 'bitString')
    der_codec = DERCodec()
    ber_codec = BERCodec()
    x208_codec = X208Codec()

    print("DER Codec:")
    print(der_codec.encode(asn1_type))
    print()

    print("BER Codec:")
    print(ber_codec.encode(asn1_type))
    print()

    print("X208 Codec:")
    print(x208_codec.encode(asn1_type))
    print()

if __name__ == "__main__":
    main()
