```python
import random

def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_keypair(p, q):
    """Generate RSA key pair."""
    # Compute n as the product of p and q
    n = p * q

    # Compute phi(n) as (p-1)(q-1)
    phi_n = (p - 1) * (q - 1)

    # Choose e as a large prime number such that 1 < e < phi(n) and gcd(e, phi(n)) = 1
    e = random.randrange(1, phi_n)
    while gcd(e, phi_n) != 1:
        e = random.randrange(1, phi_n)

    # Compute d as the modular multiplicative inverse of e modulo phi(n)
    d = pow(e, -1, phi_n)

    # Return the public and private key pairs
    return ((e, n), (d, n))

def gcd(a, b):
    """Compute the greatest common divisor of a and b."""
    while b != 0:
        a, b = b, a % b
    return a

def encrypt(public_key, message):
    """Encrypt a message using the public key."""
    e, n = public_key
    return pow(message, e, n)

def decrypt(private_key, ciphertext):
    """Decrypt a ciphertext using the private key."""
    d, n = private_key
    return pow(ciphertext, d, n)
