```python
import os
import sys
from typing import Dict, List

class Command:
    """Base command class"""
    def __init__(self, name: str, description: str, help: str):
        self.name = name
        self.description = description
        self.help = help
        self.executable = None

    def register(self, command_parser: str):
        raise NotImplementedError

    def execute(self, *args, **kwargs):
        raise NotImplementedError

class SubCommand(Command):
    """Subcommand class"""
    def __init__(self, name: str, description: str, help: str):
        super().__init__(name, description, help)

class CLI:
    """Command Line Interface class"""
    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description
        self.commands: Dict[str, Command] = {}

    def register_command(self, name: str, command: Command):
        self.commands[name] = command

    def add_subcommand(self, name: str, subcommand: SubCommand):
        self.commands[name] = subcommand

    def execute(self, args: List[str]):
        """Execute the CLI"""
        print(f"{self.name} - {self.description}")
        for command in self.commands.values():
            command.register(os.path.join(os.path.dirname(__file__), command_parser))
            command.execute(*args, **kwargs)
