# Define a parser for subcommands
def subcommand_parser(subcommand_name: str) -> str:
    """Parser for subcommands"""
    return f"{subcommand_name} - Subcommand"

# Define a parser for main commands
def main_parser() -> str:
    """Parser for main commands"""
    return "subcommand"

# Define a command to add a subcommand
def add_subcommand(parser: str) -> Command:
    """Add a subcommand"""
    return SubCommand("add", "Add a subcommand", "Add a subcommand")

# Define a command to execute a subcommand
def execute_subcommand(subcommand_name: str, *args, **kwargs) -> None:
    """Execute a subcommand"""
    return main_parser()

# Define a CLI with a parser for main commands
class MyCLI(CLI):
    def __init__(self):
        super().__init__("MyCLI", "My CLI")

    def register_command(self, name: str, command: Command):
        super().register_command(name, command)

    def add_subcommand(self, name: str, subcommand: SubCommand):
        super().add_subcommand(name, subcommand)

    def execute(self, args: List[str]):
        """Execute the CLI"""
        parser = subcommand_parser(subcommand_name="add")
        command = add_subcommand(parser)
        command.execute(args)

# Usage
cli = MyCLI()
cli.register_command("add", Command("Add a subcommand", "Add a subcommand", "Add a subcommand"))
cli.add_subcommand("add", add_subcommand(subcommand_parser("add")))
cli.execute(["add", "subcommand"])
