import pyasn1

# ASN.1 module
class ASN1Module:
    def __init__(self, asn_data):
        self.asn_data = asn_data

    def encode(self):
        return pyasn1.encode(self.asn_data)

    def decode(self, asn_string):
        return pyasn1.decode(asn_string)

# Custom ASN.1 protocol
class CustomProtocol:
    def __init__(self, protocol_id, protocol_data):
        self.protocol_id = protocol_id
        self.protocol_data = protocol_data

    def encode(self):
        return pyasn1.encode(self.protocol_data)

    def decode(self, asn_string):
        return pyasn1.decode(asn_string)

# ASN.1 module with custom protocol
class CustomASN1Module(ASN1Module):
    def __init__(self, asn_data):
        super().__init__(asn_data)
        self.custom_protocol = CustomProtocol('1.2.3', self.asn_data)

# Create an instance of the custom ASN.1 module
custom_asn1_module = CustomASN1Module(b'\x12\x34\x56\x78\x90\xab\xcd\xef')

# Encode the custom ASN.1 module
encoded_custom_asn1_module = custom_asn1_module.encode()

# Decode the encoded custom ASN.1 module
decoded_custom_asn1_module = custom_asn1_module.decode(encoded_custom_asn1_module)

# Print the custom ASN.1 protocol
print(decoded_custom_asn1_module.custom_protocol.protocol_id)  # Output: 1.2.3

Here's an example of a modular and extensible web application framework using Flask.

**Flask Application**

```python
# Import required libraries
from flask import Flask, render_template, request, jsonify

# Create a new Flask application
app = Flask(__name__)

# Define a route for the root URL
@app.route('/')
def index():
    return 'Welcome to our web application!'

# Define a route for the about page
@app.route('/about')
def about():
    return 'This is the about page.'

# Define a route for the contact page
@app.route('/contact', methods=['GET', 'POST'])
def contact():
    if request.method == 'POST':
        name = request.form['name']
        email = request.form['email']
        return f'Hello {name}, your email is {email}'
    else:
        return 'This is a GET request.'

# Define a route for the profile page
@app.route('/profile/<username>')
def profile(username):
    return f'Hello, {username}!'

# Define a route for the login page
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        # Add authentication logic here
        return f'Login successful! Username: {username}, Password: {password}'
    else:
        return 'This is a GET request.'

# Define a route for the logout page
@app.route('/logout')
def logout():
    return 'You have been logged out.'

# Define a route for the error page
@app.errorhandler(404)
def page_not_found(e):
    return '404: Page not found.', 404

# Run the application
if __name__ == '__main__':
    app.run(debug=True)
```

