import threading

# Plugin registry
plugins = {}

# Plugin hook list
plugin_hooks = []

class Plugin:
    def __init__(self, name):
        self.name = name
        self.hooks = []

    def register_hook(self, hook):
        self.hooks.append(hook)

    def run(self):
        for hook in self.hooks:
            hook()

class PluginManager:
    def __init__(self):
        self.plugins = {}
        self.lock = threading.Lock()

    def register_plugin(self, name, plugin):
        with self.lock:
            self.plugins[name] = plugin

    def call_plugins(self, name, *args, **kwargs):
        with self.lock:
            if name in self.plugins:
                for hook in self.plugins[name].hooks:
                    hook(*args, **kwargs)

def main():
    manager = PluginManager()

    def example_plugin1():
        print("Example plugin 1 executed")

    def example_plugin2():
        print("Example plugin 2 executed")

    manager.register_plugin("example_plugin1", example_plugin1)
    manager.register_plugin("example_plugin2", example_plugin2)

    def execute_plugins():
        manager.call_plugins("example_plugin1", "arg1", "arg2")
        manager.call_plugins("example_plugin2")

    threading.Thread(target=execute_plugins).start()

if __name__ == "__main__":
    main()
