class URITemplate:
    def __init__(self):
        self.template = None
        self.placeholders = {}

    def add_placeholder(self, name, value):
        self.placeholders[name] = value

    def replace(self, name, value):
        if name in self.placeholders:
            self.template = self.template.replace(name, value)
        else:
            raise ValueError(f"Unknown placeholder '{name}'")

    def __str__(self):
        return self.template


class URIParser:
    def __init__(self, template):
        self.template = template
        self.current_pos = 0

    def next(self):
        if self.current_pos < len(self.template):
            self.current_pos += 1
            return self.template[self.current_pos - 1]
        else:
            return None

    def match(self, value):
        if self.template[self.current_pos - 1] == '{':
            return True
        else:
            return False

    def parse(self, value):
        self.template = URITemplate()
        self.template.template = self.template.template
        self.template.placeholders = {}
        while self.match('{') and self.match('}'):
            placeholder = self.next()
            if placeholder == '{':
                name = self.next()
                value = self.next()
                self.template.add_placeholder(name, value)
            self.template.replace(name, value)
        return self.template


def main():
    template = '{uri: /users/{name}/posts/{id}/comments/{comments}}'
    parser = URIParser(template)
    parser.parse('users/john/posts/123/comments')
    print(parser.template)  # Output: uri: /users/john/posts/123/comments


if __name__ == '__main__':
    main()
```

