import prompt_toolkit
from prompt_toolkit.completion import WordCompleter

class CLI:
    def __init__(self):
        self.completer = WordCompleter()
        self.prompt = ">>> "

    def run(self):
        while True:
            user_input = prompt_toolkit.prompt()
            if user_input == "quit":
                break
            self.completer.add_word(user_input)
            response = self.get_response(user_input)
            print(response)


def get_response(user_input):
    """
    This function simulates a function that takes user input and returns a response.
    The response is generated based on the user's input, and it's designed to be interactive.
    """
    if user_input.lower() == "help":
        return "This is a sample CLI."
    elif user_input.lower() == "quit":
        return "Goodbye!"
    else:
        return f"Hello, {user_input}!"

if __name__ == "__main__":
    cli = CLI()
    cli.run()
