def retry_function(max_retries=3, delay=1):
    """
    A function that wraps the given code to be retried up to a specified number of times or until a specific condition is met.

    Args:
    max_retries (int): The maximum number of retries. Defaults to 3.
    delay (int): The delay in seconds between retries. Defaults to 1.

    Returns:
    function: A function that can be used to retry the original function.
    """
    def retry(func):
        def wrapper(*args, **kwargs):
            for i in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if i == max_retries - 1:
                        raise e
                    print(f"Attempt {i+1} failed. Retrying in {delay} seconds...")
                    time.sleep(delay)
        return wrapper
    return retry

# Example usage:
@retry_function(max_retries=5)
def example_function():
    raise Exception("Example exception")

example_function()

