import types

class AttributeTracker:
    def __init__(self, obj):
        self._obj = obj
        self._access_counts = {attr: 0 for attr in dir(obj)}

    def __getattr__(self, name):
        if name in self._access_counts:
            self._access_counts[name] += 1
            return self._obj[name]
        else:
            raise AttributeError(f"'{self._obj.__class__.__name__}' object has no attribute '{name}'")

    def __dir__(self):
        return [attr for attr in dir(self._obj) if not attr.startswith('__')]

# Example usage:
class MyClass:
    def __init__(self, value):
        self.value = value

obj = MyClass(10)
tracker = AttributeTracker(obj)

print(tracker._access_counts)  # {'value': 1}
print(tracker(obj.value))  # 1
print(tracker(obj)  # 2
print(tracker('non_existent_attr'))  # AttributeError: 'MyClass' object has no attribute 'non_existent_attr'
