import os
import json
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import rsa
import uuid

class Persistence:
    def __init__(self, key_file=None):
        if key_file:
            self.key = self.load_key(key_file)
        else:
            self.key = self.generate_key()

    def load_key(self, key_file):
        with open(key_file, 'rb') as key_file:
            return key_file.read()

    def generate_key(self):
        return Fernet.generate_key()

    def encrypt(self, data, key):
        fernet = Fernet(key)
        return fernet.encrypt(data.encode())

    def decrypt(self, data, key):
        fernet = Fernet(key)
        return fernet.decrypt(data).decode()

def save_data(persistence, data, filename):
    encryption_key = persistence.encrypt(data, persistence.key)
    with open(filename, 'wb') as file:
        file.write(encryption_key)

def load_data(persistence, filename):
    decryption_key = persistence.decrypt(filename, persistence.key)
    with open(filename, 'rb') as file:
        return file.read()

def generate_key_file(persistence, filename):
    key = persistence.generate_key()
    with open(filename, 'wb') as file:
        file.write(key)

def load_key_file(persistence, filename):
    with open(filename, 'rb') as file:
        return file.read()

# Create a new persistence instance
persistence = Persistence()

# Save some data
data = {'key': 'value'}
filename = 'data.json'
save_data(persistence, data, filename)

# Load the data
filename = 'data.json'
loaded_data = load_data(persistence, filename)
print(loaded_data)

# Generate a new key file
persistence.generate_key_file(persistence, 'new_key.txt')
