import typing

def _convert(data, data_type):
    """
    Helper function to convert data types.

    Args:
        data: The data to be converted.
        data_type: The target data type.

    Returns:
        The converted data.
    """
    if data_type == int:
        return int(data)
    elif data_type == float:
        return float(data)
    elif data_type == str:
        return str(data)
    elif data_type == bool:
        return bool(data)
    elif data_type == list:
        return [self._convert(item, data_type) for item in data]
    elif data_type == dict:
        return {self._convert(key, data_type): self._convert(value, data_type) for key, value in data.items()}
    else:
        return data

def convert(data, data_type):
    """
    Converts complex data types to and from native Python data types.

    Args:
        data: The data to be converted.
        data_type: The target data type.

    Returns:
        The converted data.
    """
    return _convert(data, data_type)

class ComplexData:
    def __init__(self, data):
        self.data = data

def complex_data_conversion(data):
    """
    Converts complex data types to and from native Python data types.

    Args:
        data: The complex data to be converted.

    Returns:
        The converted complex data.
    """
    if isinstance(data, ComplexData):
        return data.data
    else:
        return convert(data, ComplexData)

# Example usage
complex_data = ComplexData([1, 2, 3, 4, 5])
print(complex_data_conversion(complex_data))  # Output: [1, 2, 3, 4, 5]
```

This implementation uses a helper function `_convert` to perform the actual data type conversion. The `convert` function is a class method that uses `_convert` to perform the conversion. The `ComplexData` class is used to represent complex data, and it has a `data` attribute that is used for the conversion. The example usage demonstrates how to use the `convert` function to convert a `ComplexData` object to a list.

```python
import tornado.web
import tornado.ioloop
import tornado.websocket
import json

class TerminalSession(tornado.websocket.WebSocketHandler):
    def open(self):
        self.session = json.loads(self.request.body)
        self.update_session()

    def update_session(self):
        self.write_json({'type': 'connect', 'session': self.session})

    def on_close(self):
        self.session = None
        self.write_json({'type': 'disconnect'})

class TerminalSessionHandler(tornado.web.Application):
    def __init__(self):
        super(TerminalSessionHandler, self).__init__()
        self.add_url_pattern('/connect', TerminalSession)

    def run(self):
        tornado.web.run_app(self)

if __name__ == '__main__':
    app = TerminalSessionHandler()
    app.listen(8888)
    print("Tornado websocket backend for Xterm.js terminal emulator library running on port 8888")
