from flask_jwt_extended import JWTManager, jwt_required, create_access_token, get_jwt_identity

# Create the main application instance
app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
app.config['SECRET_KEY'] = 'secret_key_here'

# Initialize the database
db = SQLAlchemy(app)

# Initialize the Babel library
babel = Babel(app)

# Initialize the login manager
login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'

# Initialize the JWT manager
jwt = JWTManager(app)

# Initialize the mail service
mail = Mail(app)
mail.init_app(app)

# Initialize the user model
class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

# Initialize the form class
class RegistrationForm(FlaskForm):
    username = StringField('Username', validators=[InputRequired(), Length(min=4, max=80)])
    email = StringField('Email', validators=[InputRequired(), Email(), Length(min=4, max=120)])
    password = PasswordField('Password', validators=[InputRequired(), Length(min=8)])
    confirm_password = PasswordField('Confirm Password', validators=[InputRequired(), EqualTo('password')])
    submit = SubmitField('Sign Up')

# Initialize the login form
class LoginForm(FlaskForm):
    username = StringField('Username', validators=[InputRequired(), Length(min=4, max=80)])
    password = PasswordField('Password', validators=[InputRequired(), Length(min=8)])
    submit = SubmitField('Login')

# Define routes
@app.route('/')
def index():
    return 'Hello, World!'

@app.route('/register', methods=['GET', 'POST'])
def register():
    form = RegistrationForm()
    if form.validate_on_submit():
        user = User(username=form.username.data, email=form.email.data, password=form.password.data)
        db.session.add(user)
        db.session.commit()
        return 'Account created successfully!'
    return render_template('register.html', form=form)

@app.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).first()
        if user and user.password == form.password.data:
            login_user(user)
            return 'Logged in successfully!'
        else:
            return 'Invalid username or password'
    return render_template('login.html', form=form)

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return 'Logged out successfully!'

@app.route('/protected', methods=['GET', 'POST'])
@login_required
def protected():
    return 'Hello, ' + get_jwt_identity()

# Define a route for a specific route
@app.route('/admin')
@login_required
def admin():
    return 'Hello, admin!'

# Define a route for a specific route with middleware
@app.route('/admin/dashboard', methods=['GET', 'POST'])
@login_required
def admin_dashboard():
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).first()
        if user and user.password == form.password.data:
            return 'Logged in successfully!'
        else:
            return 'Invalid username or password'
    return render_template('admin/dashboard.html', form=form)

# Define a route for a specific route with authentication
@app.route('/protected/auth')
@login_required
def protected_auth():
    return 'Hello, ' + get_jwt_identity()

# Define a route for a specific route with authentication and middleware
@app.route('/protected/auth/dashboard', methods=['GET', 'POST'])
