import scipy.io as sio
import numpy as np

def read_file(file_path):
    """Read a file using scipy.io"""
    try:
        data = sio.loadmat(file_path)
        return data
    except Exception as e:
        print(f"Error reading file: {e}")

def write_file(file_path, data):
    """Write data to a file using scipy.io"""
    try:
        sio.savemat(file_path, data)
    except Exception as e:
        print(f"Error writing file: {e}")

def read_image(file_path):
    """Read an image file using scipy.io"""
    try:
        image_data = sio.imread(file_path)
        return image_data
    except Exception as e:
        print(f"Error reading image: {e}")

def read_video(file_path):
    """Read a video file using scipy.io"""
    try:
        video_data = sio.imread(file_path, asarray=True)
        return video_data
    except Exception as e:
        print(f"Error reading video: {e}")

def read_scientific_data(file_path):
    """Read scientific data from a file using scipy.io"""
    try:
        data = sio.loadmat(file_path)
        return data
    except Exception as e:
        print(f"Error reading scientific data: {e}")

def read_volumetric_data(file_path):
    """Read volumetric data from a file using scipy.io"""
    try:
        data = sio.loadmat(file_path)
        return data
    except Exception as e:
        print(f"Error reading volumetric data: {e}")
