# Import the necessary libraries
import requests
import base64
from botocore.exceptions import NoCredentialsError

# Set up AWS4 authentication
def set_aws4_auth(aws_access_key_id, aws_secret_access_key, region_name, service):
    """
    Sets up AWS4 authentication using the provided credentials and region.

    Args:
        aws_access_key_id (str): Your AWS access key ID.
        aws_secret_access_key (str): Your AWS secret access key.
        region_name (str): The name of the region to use for authentication.
        service (str): The AWS service to use for authentication.

    Returns:
        A dictionary containing the authentication details.
    """
    # Create a dictionary to store the authentication details
    auth_details = {}

    # Set up the AWS4 signature
    if service == 's3':
        # For S3, we use the IAM user's AWS credentials
        auth_details['aws4_request'] = {
            'aws4_request': {
                'method': 'GET',
                'uri': '/',
                'headers': {
                    'X-Amz-Target': '2012-11-09 AWS services API version 2012-11-09',
                    'X-Amz-User-Pattern': 'AWS'
                }
            },
            'aws4-signature': {
                'hash': 'sha1',
                'algorithm': 'HMACSHA1',
                'secret_access_key': base64.b64encode(aws_secret_access_key.encode('utf-8')).decode('utf-8')
            }
        }
    elif service == 's3s3':
        # For S3S3, we use the IAM user's AWS credentials
        auth_details['aws4_request'] = {
            'aws4_request': {
                'method': 'GET',
                'uri': '/',
                'headers': {
                    'X-Amz-Target': '2012-11-09 AWS services API version 2012-11-09',
                    'X-Amz-User-Pattern': 'AWS'
                }
            },
            'aws4-signature': {
                'hash': 'sha1',
                'algorithm': 'HMACSHA1',
                'secret_access_key': base64.b64encode(aws_secret_access_key.encode('utf-8')).decode('utf-8')
            }
        }
    else:
        raise ValueError('Unsupported service')

    # Return the authentication details
    return auth_details

# Example usage
aws_access_key_id = 'YOUR_AWS_ACCESS_KEY_ID'
aws_secret_access_key = 'YOUR_AWS_SECRET_ACCESS_KEY'
region_name = 'YOUR_REGION_NAME'
service = 's3'

auth_details = set_aws4_auth(aws_access_key_id, aws_secret_access_key, region_name, service)

# Use the authenticated requests
response = requests.get('https://s3.amazonaws.com/', auth=auth_details['aws4_request']['aws4-signature'])
print(response.status_code)
