class HumanFriendlyOutputInterface:
    def __init__(self):
        self.colors = {
            'success': '\033[92m',
            'error': '\033[91m',
            'warning': '\033[93m',
            'info': '\033[96m'
        }
        self.colors_reset = '\033[0m'

    def success(self, message):
        """Display a success message with a green color."""
        print(self.colors['success'] + message + self.colors_reset)

    def error(self, message):
        """Display an error message with a red color."""
        print(self.colors['error'] + message + self.colors_reset)

    def warning(self, message):
        """Display a warning message with a yellow color."""
        print(self.colors['warning'] + message + self.colors_reset)

    def info(self, message):
        """Display an info message with a blue color."""
        print(self.colors['info'] + message + self.colors_reset)


def main():
    output_interface = HumanFriendlyOutputInterface()

    while True:
        print("\nHuman-Friendly Output Interface")
        print("-------------------------------")
        print("1. Display Success Message")
        print("2. Display Error Message")
        print("3. Display Warning Message")
        print("4. Display Info Message")
        print("5. Quit")

        choice = input("Enter your choice: ")

        if choice == '1':
            message = "This is a success message."
            output_interface.success(message)
        elif choice == '2':
            message = "This is an error message."
            output_interface.error(message)
        elif choice == '3':
            message = "This is a warning message."
            output_interface.warning(message)
        elif choice == '4':
            message = "This is an info message."
            output_interface.info(message)
        elif choice == '5':
            print("Goodbye!")
            break
        else:
            print("Invalid choice. Please try again.")


if __name__ == "__main__":
    main()
