import json
from collections import deque

class JSONParser:
    def __init__(self, json_data):
        self.json_data = deque(json_data)
        self.position = 0

    def parse(self):
        while self.position < len(self.json_data):
            if self.json_data[self.position] == 0:
                self.position += 1
                continue

            if self.json_data[self.position] == 1:
                self.position += 1
                continue

            if self.json_data[self.position] == 2:
                value = self.json_data[self.position + 1]
                self.position += 2
                return value
            else:
                raise ValueError("Invalid JSON data")

# Usage
json_data = json.loads('{"a": 1, "b": 2, "c": 3}')
parser = JSONParser(json_data)
try:
    print(parser.parse())
except ValueError as e:
    print(e)
