from twisted.internet import reactor, pubsub

class Signal:
    def __init__(self):
        self.broadcasted_messages = {}

    def send(self, message):
        """Send a message to the broadcast channel"""
        self.broadcasted_messages[message] = True

    def broadcast(self, message):
        """Broadcast a message to all subscribers"""
        self.broadcasted_messages[message] = True

    def subscribe(self, message, callback):
        """Subscribe to a message"""
        self.broadcasted_messages[message] = True
        self.broadcast(message, callback)

class Subscriber:
    def __init__(self, name):
        self.name = name
        self.callback = None

    def subscribe(self, message, callback):
        self.callback = callback
        self.subscribe(message, callback)

def main():
    # Create a new signal
    signal = Signal()

    # Create subscribers
    subscriber1 = Subscriber("Subscriber 1")
    subscriber2 = Subscriber("Subscriber 2")

    # Subscribe to a message
    def on_message(message):
        print(f"{subscriber1.name} received message: {message}")

    subscriber1.subscribe("example", on_message)

    def on_message2(message):
        print(f"{subscriber2.name} received message: {message}")

    subscriber2.subscribe("example", on_message2)

    # Send a message to the signal
    signal.send("Hello, world!")

    # Subscribe to a broadcast message
    def on_broadcast(message):
        print(f"{subscriber1.name} received broadcast message: {message}")

    signal.subscribe("example", on_broadcast)

    # Start the reactor
    reactor.run()

if __name__ == "__main__":
    main()
```

