import os
import sys

def detect_shell():
    # Check if the script is run directly or imported
    if os.path.isfile(__file__):
        # Check the shell type based on the file extension
        if os.path.splitext(__file__)[1].lower() == '.sh':
            return 'shell'
        elif os.path.splitext(__file__)[1].lower() == '.bash' or os.path.splitext(__file__)[1].lower() == '.bashrc':
            return 'bash'
        elif os.path.splitext(__file__)[1].lower() == '.zshrc':
            return 'zsh'
        elif os.path.splitext(__file__)[1].lower() == '.fish':
            return 'fish'
        elif os.path.splitext(__file__)[1].lower() == '.tcsh':
            return 'tcsh'
        else:
            return 'sh'
    else:
        # If the script is imported, check the shell type based on the command used to run the script
        command = sys.argv[0]
        if command == os.popen('echo $SHELL').read().strip():
            return 'shell'
        elif command == os.popen('echo $SHELLRC').read().strip():
            return 'zsh'
        elif command == os.popen('echo $TERM').read().strip():
            return 'zsh'
        elif command == os.popen('echo $SHELLRC').read().strip():
            return 'zsh'
        else:
            return 'sh'

print(detect_shell())

