import difflib
from dataclasses import dataclass
from typing import Dict

@dataclass
class Object:
    """Represents a Python object with a name and attributes."""
    name: str
    attributes: Dict[str, str]

class Diff:
    """Represents a difference between two objects."""
    def __init__(self, obj1: Object, obj2: Object):
        self.obj1 = obj1
        self.obj2 = obj2

    def get_deltas(self) -> Dict[str, str]:
        """Returns a dictionary of deltas between the two objects."""
        deltas = {}
        for attr in dir(obj1):
            if not attr.startswith('__'):
                value1 = getattr(obj1, attr)
                value2 = getattr(obj2, attr)
                if value1 != value2:
                    deltas[attr] = f"{value1} -> {value2}"
        for attr in dir(obj2):
            if not attr.startswith('__'):
                value1 = getattr(obj1, attr)
                value2 = getattr(obj2, attr)
                if value1 != value2:
                    deltas[attr] = f"{value2} -> {value1}"
        return deltas

def recreate_object(obj: Object, deltas: Dict[str, str]) -> Object:
    """Recreates an object by adding deltas to each other."""
    new_obj = Object(obj.name, {})
    for attr, diff in deltas.items():
        new_obj.attributes[attr] = obj.attributes[attr] + diff
    return new_obj

def main():
    # Create two objects
    obj1 = Object("obj1", {"a": 1, "b": 2})
    obj2 = Object("obj2", {"a": 1, "b": 3})

    # Calculate the difference between the two objects
    diff = difflib.Differ()
    deltas = diff.compare(obj1, obj2)

    # Recreate obj2 by adding deltas to obj1
    obj2 = recreate_object(obj1, deltas)

    # Print the differences and the recreated object
    print("Differences:")
    for line in deltas:
        print(line)
    print("\nRecreated object:")
    for attr, value in obj2.attributes.items():
        print(f"{attr}: {value}")

if __name__ == "__main__":
    main()
