import asyncio
from fastapi import FastAPI, HTTPException, Depends, Response
from pydantic import BaseModel
from lighthouse_backend import create_note

app = FastAPI()

class Note(BaseModel):
    id: int
    title: str
    content: str

# Lighthouse database
lighthouse_db = {}

async def get_note(id: int) -> Note:
    if id not in lighthouse_db:
        raise HTTPException(status_code=404, detail="Note not found")
    return lighthouse_db[id]

async def create_note_endpoint(note: Note) -> Response:
    lighthouse_db[note.id] = note
    return Response(status_code=201, content=str(note))

async def update_note_endpoint(id: int, note: Note) -> Response:
    if id not in lighthouse_db:
        raise HTTPException(status_code=404, detail="Note not found")
    lighthouse_db[id] = note
    return Response(status_code=200)

async def delete_note_endpoint(id: int) -> Response:
    if id not in lighthouse_db:
        raise HTTPException(status_code=404, detail="Note not found")
    del lighthouse_db[id]
    return Response(status_code=204)

# Route for creating a new note
@app.post("/notes/")
async def create_note_endpoint(note: Note):
    return create_note_endpoint(note)

# Route for reading a note
@app.get("/notes/{note_id}")
async def get_note(note_id: int, request: Request):
    note = await get_note(note_id)
    if note is None:
        raise HTTPException(status_code=404, detail="Note not found")
    return note

# Route for updating a note
@app.put("/notes/{note_id}")
async def update_note(note_id: int, note: Note):
    if note_id not in lighthouse_db:
        raise HTTPException(status_code=404, detail="Note not found")
    lighthouse_db[note_id] = note
    return update_note_endpoint(note_id, note)

# Route for deleting a note
@app.delete("/notes/{note_id}")
async def delete_note(note_id: int):
    if note_id not in lighthouse_db:
        raise HTTPException(status_code=404, detail="Note not found")
    del lighthouse_db[note_id]
    return delete_note_endpoint(note_id)
