import os
import json

class VersioningSystem:
    def __init__(self, config_file):
        self.config_file = config_file
        self.version_data = self.load_version_data()

    def load_version_data(self):
        if os.path.exists(self.config_file):
            with open(self.config_file, 'r') as f:
                return json.load(f)
        else:
            return {}

    def save_version_data(self):
        with open(self.config_file, 'w') as f:
            json.dump(self.version_data, f)

    def get_latest_version(self):
        return self.version_data.get('latest_version', '1.0.0')

    def update_version(self, version):
        self.version_data['latest_version'] = version
        self.save_version_data()

    def get_version(self, version):
        return self.version_data.get(version, '1.0.0')

    def add_new_version(self, version, description):
        self.version_data[version] = description
        self.save_version_data()

    def remove_version(self, version):
        if version in self.version_data:
            del self.version_data[version]
            self.save_version_data()
        else:
            print(f"Version {version} not found.")

def main():
    config_file = 'versioning_system.json'
    versioning_system = VersioningSystem(config_file)

    while True:
        print("\nVersioning System Menu:")
        print("1. Get Latest Version")
        print("2. Update Version")
        print("3. Get Version")
        print("4. Add New Version")
        print("5. Remove Version")
        print("6. Quit")

        choice = input("Enter your choice: ")

        if choice == '1':
            print(f"Latest Version: {versioning_system.get_latest_version()}")
        elif choice == '2':
            version = input("Enter new version: ")
            description = input("Enter description: ")
            versioning_system.update_version(version, description)
        elif choice == '3':
            version = input("Enter version to get: ")
            print(f"Version: {versioning_system.get_version(version)}")
        elif choice == '4':
            version = input("Enter version to add: ")
            description = input("Enter description: ")
            versioning_system.add_new_version(version, description)
        elif choice == '5':
            version = input("Enter version to remove: ")
            versioning_system.remove_version(version)
        elif choice == '6':
            break
        else:
            print("Invalid choice. Please choose a valid option.")

if __name__ == "__main__":
    main()
