from pydantic import BaseModel, ValidationError

class Config(BaseModel):
    database_url: str

def validate_config(config: dict) -> dict:
    try:
        schema = Config.parse_raw()
        if not all(key in schema for key in config):
            raise ValidationError({
                'database_url': "Missing required key: database_url"
            }, schema=schema)
        return config
    except ValidationError as e:
        return {
            'error': str(e)
        }
