import re

def parse_version(version_string):
    """Parse a version string using semantic versioning format."""
    # Regular expression pattern for semantic versioning format
    pattern = r"(\d+)\.(\d+)\.(\d+)"
    match = re.match(pattern, version_string)

    if match:
        # Extract major, minor, and patch versions
        major, minor, patch = map(int, match.groups())
        return major, minor, patch
    else:
        raise ValueError("Invalid version string")

def compare_versions(version_string, reference_version):
    """Compare a version string to a reference version and determine if it satisfies the reference version's major, minor, and patch versions."""
    # Parse reference version
    reference_major, reference_minor, reference_patch = parse_version(reference_version)

    # Compare version string to reference version
    if reference_major == version_string[0]:
        if reference_minor == version_string[1]:
            if reference_patch == version_string[2]:
                return True
            else:
                return False
        else:
            return False
    else:
        return False

# Example usage
reference_version = "1.2.3"
version_string = "1.2.3.4"

if compare_versions(version_string, reference_version):
    print(f"{version_string} satisfies the reference version.")
else:
    print(f"{version_string} does not satisfy the reference version.")
