```python
from lxml import etree

def css_to_xpath(css_string):
    # Parse CSS3 selector
    css_tree = etree.HTML(css_string)
    css_selector = css_tree.cssselect('*')

    # Translate CSS3 to XPath 1.0
    xpath_string = ''
    for element in css_selector:
        if element.tag == 'html':
            xpath_string += '/html'
        elif element.tag == 'body':
            xpath_string += '/body'
        else:
            xpath_string += '/{}>'.format(element.tag)
        if element.count() > 1:
            xpath_string += '/{}>'.format(element.tag)

    return xpath_string

# Example usage
css_string = '''
html {
    width: 100%;
    height: 100vh;
    overflow: hidden;
}

body {
    background-color: #f2f2f2;
    padding: 20px;
}

.container {
    max-width: 800px;
    margin: 40px auto;
    padding: 20px;
    background-color: #fff;
    border: 1px solid #ddd;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

.container > * {
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}
'''

xpath_string = css_to_xpath(css_string)
print(xpath_string)
```

This code defines a function `css_to_xpath` that takes a CSS3 selector as a string, parses it using `lxml`, and translates it to an XPath 1.0 string. The example usage demonstrates how to use the function with a sample CSS3 selector.

