import asyncio
import sys

class ConsoleInterface:
    def __init__(self):
        self.commands = {}
        self.running = False

    async def run(self):
        while True:
            if not self.running:
                print("Async Console Interface")
                print("1. Execute a command")
                print("2. Quit")
                choice = input("Enter your choice: ")
                if choice == "1":
                    self.execute_command()
                elif choice == "2":
                    self.running = False
                    break
                else:
                    print("Invalid choice. Please try again.")

    async def execute_command(self):
        command = input("Enter a command: ")
        try:
            output = await self.execute_command_in_executor(None, command)
            print(output)
        except Exception as e:
            print(f"Error: {e}")

    async def execute_command_in_executor(self, func, *args, **kwargs):
        if not self.running:
            self.running = True
            task = asyncio.create_task(func(*args, **kwargs))
            await asyncio.wait([task], return_when=asyncio.FIRST_COMPLETED)
            if task.done():
                print(f"Command '{func.__name__}' executed successfully.")
                self.running = False
        else:
            print("Console is already running.")

def main():
    console_interface = ConsoleInterface()
    asyncio.run(console_interface.run())

if __name__ == "__main__":
    main()
