import json
import re

class JsonSchemaValidator:
    def __init__(self, schema):
        """
        Initialize the JsonSchemaValidator.

        Args:
            schema (dict): A dictionary representing the JSON schema to be validated.
        """
        self.schema = schema

    def validate(self, data):
        """
        Validate the input data against the JSON schema.

        Args:
            data (dict): The data to be validated.

        Returns:
            bool: True if the data is valid, False otherwise.
        """
        # Check if the input data is a dictionary
        if not isinstance(data, dict):
            return False

        # Validate the data against the schema
        for key, value in self.schema.items():
            if not self._validate_key(data, key):
                return False
            if isinstance(value, dict):
                # Recursively validate nested objects
                if not self.validate(value):
                    return False

        return True

    def _validate_key(self, data, key):
        """
        Validate a single key in the data.

        Args:
            data (dict): The data to be validated.
            key (str): The key to be validated.

        Returns:
            bool: True if the key is valid, False otherwise.
        """
        # Check if the key is present in the schema
        if key not in self.schema:
            return False

        # Get the validation rule for the key
        rule = self.schema[key]

        # Check if the value is a number
        if isinstance(rule['type'], int):
            # Check if the value is a valid number
            if not re.match(r'^-?\d+(\.\d+)?$', str(rule['value'])):
                return False

        # Check if the value is a boolean
        elif rule['type'] == 'boolean':
            # Check if the value is a valid boolean
            if not isinstance(rule['value'], bool):
                return False

        # Check if the value is a string
        elif rule['type'] == 'string':
            # Check if the value is a valid string
            if not isinstance(rule['value'], str):
                return False

        # Check if the value is a nested object
        elif rule['type'] == 'object':
            # Recursively validate the nested object
            if not self._validate_key(data, key):
                return False

        return True


# Example usage:
schema = {
    'type': 'object',
    'properties': {
        'name': {'type': 'string'},
        'age': {'type': 'integer'}
    },
    'required': ['name', 'age']
}

validator = JsonSchemaValidator(schema)

data = {
    'name': 'John Doe',
    'age': 30
}

if validator.validate(data):
    print("Data is valid")
else:
    print("Data is invalid")
```

