from flask import Flask, request, jsonify
from flask_login import LoginManager, UserMixin, login_required, login_user, logout_user, current_user
from flask_session import Session
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = "secret_key_here"
app.config["SESSION_PERMANENT"] = False
app.config["SESSION_TYPE"] = "filesystem"
Session(app)

# Initialize login manager
login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = "login"

# Define user model
class User(UserMixin):
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password, password)

# Register user
def register_user(username, password):
    user = User(username, username, password)
    db.session.add(user)
    db.session.commit()

# Login user
def login_user(username, password):
    user = User.query.filter_by(username=username).first()
    if user and user.check_password(password):
        login_user(user)
        return True
    return False

# Logout user
def logout_user():
    logout_user()
    return None

# Password hashing and verification
def hash_password(password):
    return generate_password_hash(password)

def verify_password(password, hashed_password):
    return check_password_hash(hashed_password, password)

# Login routes
@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form["username"]
        password = request.form["password"]
        if login_user(username, password):
            return jsonify({"message": "Login successful"})
    return jsonify({"message": "Invalid credentials"})

# Logout routes
@app.route("/logout", methods=["GET", "POST"])
@login_required
def logout():
    logout_user()
    return jsonify({"message": "Logged out successfully"})

# Registration routes
@app.route("/register", methods=["GET", "POST"])
def register():
    if request.method == "POST":
        username = request.form["username"]
        password = request.form["password"]
        register_user(username, password)
        return jsonify({"message": "User created successfully"})
    return jsonify({"message": "Invalid form data"})

# Password verification routes
@app.route("/verify_password/<string:password>", methods=["GET", "POST"])
def verify_password(password):
    if request.method == "POST":
        username = request.form["username"]
        hashed_password = verify_password(password, hash_password(password))
        return jsonify({"password": hashed_password})
    return jsonify({"message": "Invalid password"})

if __name__ == "__main__":
    app.run(debug=True)
```

This code implements user authentication and session management for Flask using `flask_login` and `flask_session`. It includes login and logout routes, user registration and login functionality, and password hashing and verification.

