def create_person():
    """Creates a Person dataclass instance."""
    return Person("John Doe", 30)

# Create a JSON string from the dataclass instance
def create_json_string(person):
    """Creates a JSON string from a Person dataclass instance."""
    return json.dumps(person, default=str)

# Deserialize the JSON string back into a dataclass instance
def create_dataclass_instance(json_string):
    """Deserializes a JSON string back into a Person dataclass instance."""
    return json.loads(json_string)

# Example usage
json_string = create_json_string(create_person())
print("JSON String:", json_string)

dataclass_instance = create_dataclass_instance(json_string)
print("Dataclass Instance:", dataclass_instance)
