from typing import TypeVar, Generic, Sequence, Mapping, Dict
from collections.abc import Mapping, Sequence, Generic

T = TypeVar('T')

class MappingType(Generic[T], Mapping[T, T]):
    def __missing__(self, key: T) -> T:
        raise KeyError(key)

    def __setitem__(self, key: T, value: T) -> None:
        raise AttributeError(key)

    def __contains__(self, key: T) -> bool:
        return key in self

class SequenceType(Generic[T], Sequence[T]):
    def __getitem__(self, index: int) -> T:
        raise IndexError

    def __len__(self) -> int:
        return len(self)

    def __contains__(self, item: T) -> bool:
        return item in self

class GenericMappingType(Generic[T, U], Mapping[T, U]):
    def __missing__(self, key: T) -> U:
        raise KeyError(key)

    def __setitem__(self, key: T, value: U) -> None:
        raise AttributeError(key)

    def __contains__(self, key: T) -> bool:
        return key in self

    def __iter__(self) -> iter[U]:
        return iter(self.values())

class GenericSequenceType(Generic[T, U], Sequence[T]):
    def __getitem__(self, index: int) -> U:
        raise IndexError

    def __len__(self) -> int:
        return len(self)

    def __contains__(self, item: U) -> bool:
        return item in self

    def __iter__(self) -> iter[U]:
        return iter(self)

class SequenceMappingType(Generic[T, U], Mapping[T, U]):
    def __missing__(self, key: T) -> U:
        raise KeyError(key)

    def __setitem__(self, key: T, value: U) -> None:
        raise AttributeError(key)

    def __contains__(self, key: T) -> bool:
        return key in self

    def __iter__(self) -> iter[U]:
        return iter(self.items())

class MappingSequenceType(Generic[T, U], Sequence[Mapping[T, U]]):
    def __getitem__(self, index: int) -> Mapping[T, U]:
        raise IndexError

    def __len__(self) -> int:
        return len(self)

    def __contains__(self, item: Mapping[T, U]) -> bool:
        return item in self

    def __iter__(self) -> iter[Mapping[T, U]]:
        return iter(self)

class SequenceMappingType(Generic[T, U], Sequence[Mapping[T, U]]):
    def __getitem__(self, index: int) -> Mapping[T, U]:
        raise IndexError

    def __len__(self) -> int:
        return len(self)

    def __contains__(self, item: Mapping[T, U]) -> bool:
        return item in self

    def __iter__(self) -> iter[Mapping[T, U]]:
        return iter(self)
