class ExceptionGroup:
    def __init__(self, *exceptions):
        self.exceptions = exceptions

    def __repr__(self):
        return f"ExceptionGroup({self.exceptions})"

    def __str__(self):
        return f"ExceptionGroup({self.exceptions})"

    def __and__(self, other):
        if isinstance(other, ExceptionGroup):
            return ExceptionGroup(self.exceptions | other.exceptions)
        else:
            raise TypeError("Only ExceptionGroup instances can be chained together")

    def __or__(self, other):
        if isinstance(other, ExceptionGroup):
            return ExceptionGroup(self.exceptions | other.exceptions)
        else:
            raise TypeError("Only ExceptionGroup instances can be chained together")
