```python
from datetime import datetime
import time

def format_timestamp(timestamp):
    """Format a timestamp in seconds since epoch as a human-readable string."""
    return f"{timestamp // 1000:02d}:{(timestamp % 1000) // 100:02d}:{timestamp % 100:02d}"

def format_filesize(filesize):
    """Format a file size in bytes as a human-readable string."""
    return f"{filesize // 1024:02d} KB {filesize % 1024:02d} B"

def format_decimal(num):
    """Simplify decimal numbers by rounding to two decimal places."""
    return "{:.2f}".format(num)

def convert_to_human_readable(date_time):
    """Convert date and time to human-readable format."""
    return datetime(date_time.year, date_time.month, date_time.day, date_time.hour, date_time.minute, date_time.second).strftime("%Y-%m-%d %H:%M:%S")

def simplify_decimal(num):
    """Simplify decimal numbers by removing trailing zeros."""
    return "{:,.2f}".format(num)

def main():
    # Example usage:
    timestamp = int(time.time())
    print(format_timestamp(timestamp))
    filesize = 1024 * 1024 * 5  # 5 GB
    print(format_filesize(filesize))
    date_time = datetime(2022, 9, 1, 12, 0, 0)  # September 1, 2022, 12:00:00
    print(convert_to_human_readable(date_time))
    num = 3.14159265359  # pi
    print(simplify_decimal(num))

if __name__ == "__main__":
    main()
```

