from urllib.parse import (
    urlsplit, urlunsplit, urlencode, unquote, quote, urljoin,
    urlparse, urlunparse
)

def split_url(url):
    """Split a URL into its components."""
    return urlsplit(url)

def combine_url_parts(url_parts):
    """Combine URL parts."""
    return urlunsplit(url_parts)

def resolve_relative_url(base_url, relative_url):
    """Resolve a relative URL to an absolute URL."""
    return urljoin(base_url, relative_url)

def encode_url_component(url_component):
    """Encode a URL component."""
    return unquote(url_component)

def decode_url_component(url_component):
    """Decode a URL component."""
    return quote(url_component, safe=':/?@#')

def encode_url(url):
    """Encode a URL."""
    return urlunparse((encode_url_component(url.split('://')[-1]), 
                      encode_url_component(url.split('/')[1]), 
                      encode_url_component(url.split('/')[2]), 
                      encode_url_component(url.split('/')[3]), 
                      encode_url_component(url.split('/')[4]), 
                      decode_url_component(url.split('/')[5])))

def decode_url(url):
    """Decode a URL."""
    return urlunparse((decode_url_component(url.split('://')[-1]), 
                      decode_url_component(url.split('/')[1]), 
                      decode_url_component(url.split('/')[2]), 
                      decode_url_component(url.split('/')[3]), 
                      decode_url_component(url.split('/')[4]), 
                      decode_url_component(url.split('/')[5])))
```

