```python
class Node:
    """Represents a node in the binary search tree."""

    def __init__(self, key, value):
        """Initializes a new node with a key and value."""

        self.key = key
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    """Represents a binary search tree."""

    def __init__(self):
        """Initializes an empty binary search tree."""

        self.root = None

    def insert(self, key, value):
        """Inserts a new key-value pair into the binary search tree."""

        if self.root is None:
            self.root = Node(key, value)
        else:
            self._insert(self.root, key, value)

    def _insert(self, node, key, value):
        """Recursively inserts a new key-value pair into the binary search tree."""

        if key < node.key:
            if node.left is None:
                node.left = Node(key, value)
            else:
                self._insert(node.left, key, value)
        else:
            if node.right is None:
                node.right = Node(key, value)
            else:
                self._insert(node.right, key, value)

    def delete(self, key):
        """Deletes a key-value pair from the binary search tree."""

        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Recursively deletes a key-value pair from the binary search tree."""

        if node is None:
            return node
        elif key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                # Find the minimum value in the right subtree
                min_node = self._find_min(node.right)
                node.key = min_node.key
                node.value = min_node.value
                node.right = self._delete(node.right, min_node.key)
        return node

    def _find_min(self, node):
        """Finds the minimum value in a subtree."""

        while node.left is not None:
            node = node.left
        return node

    def get(self, key):
        """Retrieves the value associated with a key."""

        return self._get(self.root, key)

    def _get(self, node, key):
        """Recursively retrieves the value associated with a key."""

        if node is None:
            return None
        elif key < node.key:
            return self._get(node.left, key)
        elif key > node.key:
            return self._get(node.right, key)
        else:
            return node.value

    def keys(self):
        """Returns a list of all keys in the binary search tree."""

        return [key for key, value in self.root.items()]

    def values(self):
        """Returns a list of all values in the binary search tree."""

        return [value for key, value in self.root.items()]

# Example usage
bst = BinarySearchTree()
bst.insert(5, "Five")
bst.insert(3, "Three")
bst.insert(7, "Seven")
bst.insert(2, "Two")
bst.insert(4, "Four")

print(bst.get(5))  # Output: Five
print(bst.get(3))  # Output: Three
print(bst.get(7))  # Output: Seven
print(bst.get(2))  # Output: Two
print(bst.get(4))  # Output: Four

bst.delete(3)
print(bst.get(3))  # Output: None
```

