class BaseClass:
    def __init__(self):
        """
        Base class constructor.

        Initializes the base class with an empty dictionary.
        """
        self.base_attributes = {}

    def __getattr__(self, name):
        """
        Gets the attribute from the base class.

        If the attribute is not found in the base class, it raises an AttributeError.

        Args:
            name (str): The name of the attribute to get.

        Returns:
            The attribute value.

        Raises:
            AttributeError: If the attribute is not found in the base class.
        """
        if name in self.base_attributes:
            return self.base_attributes[name]
        else:
            raise AttributeError(f"Attribute '{name}' not found in base class.")

    def set_base_attribute(self, name, value):
        """
        Sets the base attribute in the base class.

        Args:
            name (str): The name of the attribute to set.
            value (any): The value of the attribute to set.

        Returns:
            None
        """
        self.base_attributes[name] = value

class MyClass(BaseClass):
    def __init__(self):
        super().__init__()
        self.my_base_attribute = "base attribute value"

    def __getattr__(self, name):
        if name == "my_base_attribute":
            return self.my_base_attribute
        else:
            return super().__getattr__(name)

    def set_my_base_attribute(self, value):
        self.set_base_attribute("my_base_attribute", value)

    def get_my_base_attribute(self):
        return self.get_base_attribute("my_base_attribute")


# Example usage:
obj = MyClass()
print(obj.my_base_attribute)  # Output: base attribute value
obj.set_my_base_attribute("new value")
print(obj.my_base_attribute)  # Output: new value

obj.get_my_base_attribute()  # Output: new value
```

