import argparse

def main():
    # Create the argument parser
    parser = argparse.ArgumentParser(description='A simple CLI tool for managing tasks.')

    # Define a list of subcommands
    subcommands = [
        'task list',
        'task create',
        'task delete',
        'task update'
    ]

    # Define a list of arguments for each subcommand
    args = {
        'task list': ['--name', '--description'],
        'task create': ['--name', '--description', '--priority'],
        'task delete': ['--id'],
        'task update': ['--id', '--name', '--description', '--priority']
    }

    # Parse the command-line arguments
    try:
        # Parse the arguments
        args = parser.parse_args()

        # Handle the subcommand
        if args.subcommand in subcommands:
            # Execute the corresponding function
            if args.subcommand == 'task list':
                print('Task List:')
                for task in get_tasks():
                    print(task)
            elif args.subcommand == 'task create':
                create_task(args)
            elif args.subcommand == 'task delete':
                delete_task(args)
            elif args.subcommand == 'task update':
                update_task(args)
        else:
            print('Invalid subcommand')
    except argparse.ArgumentError as e:
        print(f'Error: {e}')

def get_tasks():
    # Simulate getting tasks from a database
    return [
        {'id': 1, 'name': 'Task 1', 'description': 'This is task 1', 'priority': 1},
        {'id': 2, 'name': 'Task 2', 'description': 'This is task 2', 'priority': 2}
    ]

def create_task(args):
    # Simulate creating a new task
    task = {
        'id': args.id,
        'name': args.name,
        'description': args.description,
        'priority': args.priority
    }
    print(f'Task created: {task}')

def delete_task(args):
    # Simulate deleting a task
    if args.id in [1, 2]:
        print(f'Task {args.id} deleted')
    else:
        print('Invalid task ID')

def update_task(args):
    # Simulate updating a task
    if args.id in [1, 2]:
        task = {
            'id': args.id,
            'name': args.name,
            'description': args.description,
            'priority': args.priority
        }
        print(f'Task {args.id} updated: {task}')
    else:
        print('Invalid task ID')

if __name__ == '__main__':
    main()
```

