import argparse

class CustomParser(argparse.ArgumentParser):
    def add_config_file(self, parser, config_file):
        parser.add_argument('--config-file', type=str, default='config.json', help='Path to the configuration file')

    def add_env_var(self, parser, var_name, var_value):
        parser.add_argument('--' + var_name, type=var_value.__class__, help='Environment variable value')

    def parse_args(self):
        args = super().parse_args()
        if args.config_file:
            with open(args.config_file, 'r') as f:
                config = json.load(f)
                for key, value in config.items():
                    setattr(args, key, value)
        if args.env_var:
            for key, value in vars(args).items():
                setattr(args, key, value)
        return args
