import functools
import warnings

@functools.wraps
def deprecated_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        warnings.warn(f"Deprecated function {func.__name__} is being wrapped. Please use `@functools.wraps(func)` to preserve the original function's metadata.", DeprecationWarning)
        return func(*args, **kwargs)
    return wrapper

# Example usage:
@deprecated_decorator
def deprecated_function(x, y):
    return x + y

@deprecated_decorator
def new_function(x, y):
    return x * y
