```python
import os
import subprocess

class ProcessController:
    def __init__(self):
        self.current_state = 'stopped'

    def start(self):
        """Start a new process and transition to running state."""
        if self.current_state == 'stopped':
            command = ['bash', '-c', 'echo "Starting new process"']
        else:
            command = ['bash', '-c', 'echo "Process is already running"']

        output = subprocess.run(command, shell=True, check=True)
        if output.returncode == 0:
            self.current_state = 'running'
            print(f"Process started successfully")
        else:
            print(f"Failed to start process: {output.stderr}")

    def stop(self):
        """Stop the current process and transition to stopped state."""
        if self.current_state == 'running':
            command = ['bash', '-c', 'echo "Stopping process"']
        else:
            command = ['bash', '-c', 'echo "Process is already stopped"']

        output = subprocess.run(command, shell=True, check=True)
        if output.returncode == 0:
            self.current_state = 'stopped'
            print(f"Process stopped successfully")
        else:
            print(f"Failed to stop process: {output.stderr}")

    def restart(self):
        """Restart the current process and transition to running state."""
        if self.current_state == 'stopped':
            command = ['bash', '-c', 'echo "Restarting process"']
        else:
            command = ['bash', '-c', 'echo "Process is already running"']

        output = subprocess.run(command, shell=True, check=True)
        if output.returncode == 0:
            self.current_state = 'running'
            print(f"Process restarted successfully")
        else:
            print(f"Failed to restart process: {output.stderr}")

    def status(self):
        """Print the current process state."""
        print(f"Current state: {self.current_state}")

controller = ProcessController()

while True:
    print("\nProcess Controller Menu:")
    print("1. Start process")
    print("2. Stop process")
    print("3. Restart process")
    print("4. Print status")
    print("5. Exit")

    choice = input("Enter your choice: ")

    if choice == '1':
        controller.start()
    elif choice == '2':
        controller.stop()
    elif choice == '3':
        controller.restart()
    elif choice == '4':
        controller.status()
    elif choice == '5':
        break
    else:
        print("Invalid choice. Please try again.")
```

```python
import sympy as sp

class CAS:
    def __init__(self):
        self.variables = {}
        self expressions = []

    def add_variable(self, var):
        self.variables[var] = None

    def add_expression(self, expr):
        self.expressions.append(expr)

    def evaluate_expression(self, var, expr):
        try:
            result = sp.simplify(sp.sympify(expr))
            self.variables[var] = result
            return result
        except sp.SympifyError:
            return None

    def differentiate_expression(self, var, expr):
        try:
            result = sp.diff(sp.sympify(expr), var)
            self.variables[var] = result
            return result
        except sp.SympifyError:
            return None

    def integrate_expression(self, var, expr):
        try:
            result = sp.integrate(sp.sympify(expr), var)
            self.variables[var] = result
            return result
        except sp.SympifyError:
            return None

    def solve_equation(self, var, expr):
        try:
            solution = sp.solve(sp.sympify(expr), var)
            self.variables[var] = solution
            return solution
        except sp.SympifyError:
            return None

    def display CAS(self):
        print("Variables:")
        for var, value in self.variables.items():
            print(f"{var}: {value}")

        print("\nExpressions:")
        for expr in self.expressions:
            print(expr)

        print("\nResults:")
        for var, result in self.variables.items():
            if result is not None:
                print(f"{var}: {result}")

        print("\nResults of Differentiation:")
        for var, result in self.variables.items():
            if result is not None:
                print(f"{var}: {result}")

        print("\nResults of Integration:")
        for var, result in self.variables.items():
            if result is not None:
                print(f"{var}: {result}")

        print("\nResults of Solving Equations:")
        for var, result in self.variables.items():
            if result is not None:
                print(f"{var}: {result}")

# Example usage
cas = CAS()
cas.add_variable("x")
cas.add_expression("x**2 + 2*x + 1")
cas.add_expression("x**2 - 4*x + 4")

cas.evaluate_expression("x", "x**2 + 2*x + 1")
cas.evaluate_expression("x", "x**2 - 4*x + 4")

cas.differentiate_expression("x", "x**2 + 2*x + 1")
cas.differentiate_expression("x", "x**2 - 4*x + 4")

cas.integrate_expression("x", "x**2 + 2*x + 1")
cas.integrate_expression("x", "x**2 - 4*x + 4")

cas.solve_equation("x", "x**2 + 2*x + 1")
cas.solve_equation("x", "x**2 - 4*x + 4")

cas.display CAS()
```

