import ast

def validate_docstrings(code):
    try:
        tree = ast.parse(code, mode='eval')
        for node in ast.walk(tree):
            if isinstance(node, ast Docstring):
                if not isinstance(node.value, str):
                    raise Exception("Invalid docstring format")
                if not node.value.strip().startswith('"""') and not node.value.strip().startswith("'''"):
                    raise Exception("Invalid docstring format")
                if not node.value.strip().startswith('"""') or not node.value.strip().startswith("'''"):
                    raise Exception("Invalid docstring format")
    except Exception as e:
        raise Exception("Validation error: " + str(e))

# Example usage
code = """
def my_function():
    """
    This is a sample docstring.
    """
    print("Hello World")
"""

validate_docstrings(code)
```
